   314→		 * @return value of label param for this form component
   315→		 */
   316→		private String getLabel()
   317→		{
   318→			String label = null;
   319→
   320→			// first try the label model ...
   321→			if (getFormComponent().getLabel() != null)
   322→			{
   323→				label = getFormComponent().getLabel().getObject();
   324→			}
   325→			// ... then try a resource of format [form-component-id] with
   326→			// default of '[form-component-id]'
   327→			if (label == null)
   328→			{
   329→
   330→				label = getFormComponent().getDefaultLabel();
   331→			}
   332→			return label;
   333→		}
   334→	}
